lib = '''def solid_rows(grid):
    """Rows that are a single uniform nonzero color."""
    return [(i, row[0]) for i, row in enumerate(grid)
            if len(set(row)) == 1 and row[0] != 0]

def phase_tile(rows):
    """Colored row i keeps its position modulo the count of colored rows."""
    n = len(rows)
    tile = [None] * n
    for i, c in rows:
        tile[i % n] = c
    return tile

def tile_rows(tile, height, width):
    """Repeat the tile cyclically to fill the grid."""
    n = len(tile)
    return [[tile[i % n]] * width for i in range(height)]

def transform_solid(grid):
    height, width = len(grid), len(grid[0])
    return tile_rows(phase_tile(solid_rows(grid)), height, width)

def transform_diagonal(grid):
    """Extend diagonal stripes: every cell takes the color of its
    (j - i) mod m stripe class, m the smallest consistent modulus."""
    height, width = len(grid), len(grid[0])
    for m in range(2, max(width, height) + 1):
        cls = {}
        ok = True
        for i, row in enumerate(grid):
            for j, v in enumerate(row):
                if v != 0:
                    c = (j - i) % m
                    if cls.setdefault(c, v) != v:
                        ok = False
                        break
            if not ok:
                break
        if ok and len(cls) == m:
            return [[cls[(j - i) % m] for j in range(width)] for i in range(height)]
    raise ValueError("no consistent modulus")
